package main

import (
	"fmt"
	"sync"
)

func main() {
	var mu sync.Mutex
	contador := 0
	var wg sync.WaitGroup

	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			mu.Lock()         // Bloqueia acesso concorrente
			contador++
			mu.Unlock()       // Libera para outras goroutines
		}()
	}
	wg.Wait()
	fmt.Println("Contador protegido:", contador)
}

